def rk4_step(f, t, y, h):
    k1 = f(t, y)
    k2 = f(t + h / 2, y + h / 2 * k1)
    k3 = f(t + h / 2, y + h / 2 * k1)
    k4 = f(t + h, y + h * k3)
    return y + h / 6 * (k1 + 2 * k2 + 2 * k3 + k4)

import numpy as np
def f(u):
    return np.exp(u)
def antithetic(n, seed):
    out = []
    for i in range(n):
        u1 = np.random.default_rng(seed + 2 * i).random()
        u2 = 1 - np.random.default_rng(seed + 2 * i + 1).random()
        out.append((f(u1) + f(u2)) / 2)
    return np.mean(out)
